import React, { useState } from 'react';
import useScheduleStore from '../store/useScheduleStore';
import { Card } from '../components/ui/Card';
import { Calendar as CalendarIcon, ChevronLeft, ChevronRight, Plus, Users, Clock } from 'lucide-react';
import { Modal } from '../components/ui/Modal';
import { BillingModal } from '../components/schedule/BillingModal';

const HOURS = Array.from({ length: 13 }, (_, i) => i + 9);

const SchedulePage = () => {
  const { appointments } = useScheduleStore();
  const [isModalOpen, setIsModalOpen] = useState(false);
  const[endingAppointment, setEndingAppointment] = useState(null);

  const getStyleForTime = (timeStr, durationStr) => {
    const [h, m] = timeStr.split(':').map(Number);
    const top = (h - 9) * 60 + (m / 60) * 60;
    const height = (durationStr / 60) * 60;
    return { top: `${top}px`, height: `${height}px` };
  };

  return (
      <div className="flex flex-col h-[calc(100vh-8rem)] md:h-[calc(100vh-6rem)] min-w-0 relative">

        {/* Шапка адаптированная: flex-col на мобилке, flex-row на десктопе */}
        <div className="flex flex-col mb-4 gap-3 shrink-0">
          <div className="flex flex-col sm:flex-row justify-between gap-3">
            <div className="flex w-full sm:w-auto items-center justify-between bg-white border border-gray-200 rounded-xl p-1 shadow-sm">
              <button className="p-2 hover:bg-gray-50 rounded-lg text-gray-500"><ChevronLeft size={16} /></button>
              <div className="px-2 py-1 flex items-center gap-2 font-medium text-sm text-gray-800">
                <CalendarIcon size={14} className="text-brand-500" /> 10 Мая
              </div>
              <button className="p-2 hover:bg-gray-50 rounded-lg text-gray-500"><ChevronRight size={16} /></button>
            </div>

            <div className="flex w-full sm:w-auto bg-gray-100 p-1 rounded-xl text-sm font-medium">
              <button className="flex-1 sm:flex-none bg-white shadow-sm px-4 py-1.5 rounded-lg text-gray-900 text-center">День</button>
              <button className="flex-1 sm:flex-none px-4 py-1.5 rounded-lg text-gray-500 hover:text-gray-900 text-center">Неделя</button>
            </div>
          </div>

          <div className="flex flex-col sm:flex-row sm:justify-end gap-3">
            <button className="w-full sm:w-auto flex items-center justify-center gap-2 px-4 py-2.5 border border-gray-200 bg-white rounded-xl text-sm font-medium hover:bg-gray-50">
              <Users size={16} /> Все врачи
            </button>
            <button
                onClick={() => setIsModalOpen(true)}
                className="w-full sm:w-auto flex items-center justify-center gap-2 px-4 py-2.5 bg-brand-600 text-white rounded-xl text-sm font-medium hover:bg-brand-700 shadow-sm transition-colors"
            >
              <Plus size={16} /> Новая запись
            </button>
          </div>
        </div>

        {/* Скролл таблицы */}
        <Card className="flex-1 overflow-x-auto overflow-y-auto p-0 rounded-2xl relative hide-scrollbar border-gray-200 flex flex-col w-full">
          <div className="flex flex-col min-w-[600px] h-full">
            <div className="sticky top-0 bg-gray-50 border-b border-gray-200 z-30 flex text-sm font-medium text-gray-500 text-center shadow-sm">
              <div className="w-16 sm:w-20 border-r border-gray-200 py-3 bg-gray-50">Время</div>
              <div className="flex-1 border-r border-gray-200 py-3 bg-white text-gray-900">Кабинет 1 (Терапия)</div>
              <div className="flex-1 py-3 bg-white text-gray-900">Кабинет 2 (Груминг)</div>
            </div>

            <div className="flex flex-1 relative min-h-[780px]">
              <div className="w-16 sm:w-20 border-r border-gray-200 flex flex-col bg-gray-50 absolute left-0 top-0 bottom-0 z-10">
                {HOURS.map(hour => (
                    <div key={hour} className="h-[60px] border-b border-gray-200 flex items-start justify-center pt-2 text-xs text-gray-500 font-medium">
                      {`${hour}:00`}
                    </div>
                ))}
              </div>

              <div className="flex-1 flex ml-16 sm:ml-20 relative">
                <div className="absolute inset-0 pointer-events-none z-0 opacity-50">
                  {HOURS.map(hour => <div key={hour} className="h-[60px] border-b border-gray-100 border-dashed w-full" />)}
                </div>

                <div className="flex-1 border-r border-gray-100 relative">
                  {appointments.filter(a =>['1','2'].includes(a.id)).map(app => (
                      <div
                          key={app.id}
                          className="absolute left-1 right-1 sm:left-2 sm:right-2 bg-brand-50 border border-brand-200 rounded-xl p-2 shadow-sm hover:shadow-md transition-all cursor-pointer overflow-hidden z-20 group flex flex-col"
                          style={getStyleForTime(app.time, app.durationMinutes)}
                      >
                        <div className="flex-1">
                          <div className="text-[10px] sm:text-xs font-bold text-brand-900 line-clamp-1">{app.title}</div>
                          <div className="text-[9px] sm:text-[10px] text-brand-600 mt-0.5 truncate">{app.service}</div>
                          <div className="text-[9px] sm:text-[10px] text-brand-500 mt-1 flex gap-1 items-center">
                            <Clock size={10} /> {app.time}
                          </div>
                        </div>
                        <div className="mt-auto pt-1 hidden group-hover:block">
                          <button onClick={(e) => { e.stopPropagation(); setEndingAppointment(app); }} className="w-full text-center bg-brand-600 text-white text-[10px] font-bold py-1 rounded shadow-sm">
                            Завершить
                          </button>
                        </div>
                      </div>
                  ))}
                </div>

                <div className="flex-1 relative">
                  {appointments.filter(a => ['3'].includes(a.id)).map(app => (
                      <div
                          key={app.id}
                          className="absolute left-1 right-1 sm:left-2 sm:right-2 bg-purple-50 border border-purple-200 rounded-xl p-2 shadow-sm hover:shadow-md transition-all cursor-pointer overflow-hidden z-10 group"
                          style={getStyleForTime(app.time, app.durationMinutes)}
                      >
                        <div className="text-[10px] sm:text-xs font-bold text-purple-900 line-clamp-1">{app.title}</div>
                        <div className="text-[9px] sm:text-[10px] text-purple-700 mt-0.5 truncate">{app.service}</div>
                      </div>
                  ))}
                </div>
              </div>
            </div>
          </div>
        </Card>

        <Modal isOpen={isModalOpen} onOpenChange={setIsModalOpen} title="Новая запись">
          <div className="flex flex-col gap-4 mt-2">
            <input type="text" placeholder="Клиент / Питомец" className="w-full px-3 py-2 border border-gray-200 rounded-xl bg-gray-50 focus:bg-white" />
            <div className="grid grid-cols-2 gap-4">
              <input type="time" defaultValue="14:00" className="w-full px-3 py-2 border border-gray-200 rounded-xl bg-gray-50 focus:bg-white" />
              <select className="w-full px-3 py-2 border border-gray-200 rounded-xl bg-gray-50 focus:bg-white text-sm">
                <option>Кабинет 1</option>
                <option>Кабинет 2</option>
              </select>
            </div>
            <button className="w-full bg-brand-600 text-white rounded-xl py-3 font-bold hover:bg-brand-700">Сохранить</button>
          </div>
        </Modal>

        <BillingModal isOpen={!!endingAppointment} onClose={() => setEndingAppointment(null)} appointmentInfo={endingAppointment} />
      </div>
  );
};

export default SchedulePage;