import React, { useState } from 'react';
import { Card } from '../components/ui/Card';
import { Badge } from '../components/ui/Badge';
import { PhoneCall, Mic, MicOff, Video, VideoOff, PhoneOff, Send, MessageSquareHeart } from 'lucide-react';
import { cn } from '../components/ui/Card';

const SosPage = () => {
  const[isOnDuty, setIsOnDuty] = useState(false);
  const [inCall, setInCall] = useState(false);
  const [micOn, setMicOn] = useState(true);
  const[camOn, setCamOn] = useState(true);

  const toggleDuty = () => {
    const newState = !isOnDuty;
    setIsOnDuty(newState);
    if(newState && !inCall) setTimeout(() => setInCall(true), 2000);
    else setInCall(false);
  };

  return (
      <div className="flex flex-col h-[calc(100vh-7rem)] min-w-0">

        {/* Шапка SOS с правильным переносом на мобилке */}
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-4 shrink-0 bg-white p-4 sm:p-5 rounded-2xl shadow-sm border border-gray-100">
          <div>
            <h2 className="text-xl font-bold tracking-tight text-gray-900">Экстренный хаб (SOS)</h2>
            <p className="text-sm text-gray-500 mt-1">Дежурный врач: Елена В.</p>
          </div>

          <div className="flex items-center justify-between sm:justify-end gap-3 pt-4 sm:pt-0 border-t border-gray-100 sm:border-0 w-full sm:w-auto">
          <span className={cn("text-sm font-bold", isOnDuty ? "text-green-600" : "text-gray-500")}>
            {isOnDuty ? "Дежурство активно" : "Отключено"}
          </span>
            <button
                onClick={toggleDuty}
                className={cn("relative inline-flex h-8 w-14 items-center rounded-full transition-colors focus:outline-none", isOnDuty ? "bg-green-500" : "bg-gray-200")}
            >
              <span className={cn("inline-block h-6 w-6 transform rounded-full bg-white transition-transform shadow-sm", isOnDuty ? "translate-x-7" : "translate-x-1")} />
            </button>
          </div>
        </div>

        {!isOnDuty && (
            <div className="flex-1 flex flex-col items-center justify-center bg-gray-50/50 rounded-2xl border-2 border-dashed border-gray-200 p-6 text-center">
              <PhoneCall size={48} className="text-gray-300 mb-4" />
              <h3 className="text-lg font-bold text-gray-700">Ожидание вызовов</h3>
              <p className="text-sm text-gray-500 mt-2 max-w-sm">Включите ползунок дежурства, чтобы начать принимать онлайн-консультации из Ozon.</p>
            </div>
        )}

        {isOnDuty && !inCall && (
            <div className="flex-1 flex flex-col items-center justify-center bg-green-50/30 rounded-2xl border-2 border-dashed border-green-200 p-6 text-center">
              <div className="relative">
                <div className="absolute inset-0 bg-green-400 rounded-full animate-ping opacity-20"></div>
                <div className="relative w-20 h-20 bg-green-100 text-green-600 rounded-full flex items-center justify-center shadow-sm">
                  <PhoneCall size={28} />
                </div>
              </div>
              <h3 className="text-lg font-bold text-gray-800 mt-6">Вы на линии</h3>
              <p className="text-sm text-gray-500 mt-1">Ожидаем соединение...</p>
            </div>
        )}

        {isOnDuty && inCall && (
            <div className="flex-1 flex flex-col lg:flex-row gap-4 overflow-hidden">

              <div className="flex-1 bg-gray-900 rounded-2xl relative overflow-hidden flex flex-col min-h-[300px]">
                <div className="absolute top-4 left-4 z-10 flex gap-2">
                  <Badge variant="destructive" className="animate-pulse px-2 text-[10px] md:text-xs">🔴 LIVE</Badge>
                  <span className="bg-black/50 backdrop-blur-md text-white text-[10px] md:text-xs font-mono px-2 py-1 rounded-lg">00:03:45</span>
                </div>

                <div className="flex-1 flex items-center justify-center p-4">
                  {camOn ? (
                      <div className="text-center">
                        <div className="w-24 h-24 md:w-32 md:h-32 rounded-full border-4 border-gray-700 border-dashed mx-auto mb-4 flex items-center justify-center text-4xl bg-gray-800">🐶</div>
                        <p className="text-gray-400 font-medium text-sm">Ожидание видео от клиента</p>
                      </div>
                  ) : (
                      <VideoOff size={48} className="text-gray-700" />
                  )}
                </div>

                <div className="absolute bottom-4 left-1/2 -translate-x-1/2 bg-gray-800/80 backdrop-blur-lg px-4 py-3 md:px-6 rounded-full flex items-center gap-3 shadow-xl">
                  <button onClick={() => setMicOn(!micOn)} className={cn("w-12 h-12 rounded-full flex items-center justify-center", micOn ? "bg-gray-700 text-white" : "bg-red-500 text-white")}>
                    {micOn ? <Mic size={18} /> : <MicOff size={18} />}
                  </button>
                  <button onClick={() => setCamOn(!camOn)} className={cn("w-12 h-12 rounded-full flex items-center justify-center", camOn ? "bg-gray-700 text-white" : "bg-red-500 text-white")}>
                    {camOn ? <Video size={18} /> : <VideoOff size={18} />}
                  </button>
                  <button onClick={() => setInCall(false)} className="w-16 h-12 rounded-full bg-red-600 text-white flex items-center justify-center ml-2">
                    <PhoneOff size={18} />
                  </button>
                </div>
              </div>

              <Card className="w-full lg:w-80 flex flex-col p-5 bg-white overflow-y-auto hide-scrollbar max-h-[50vh] lg:max-h-full shrink-0">
                <div className="flex items-center lg:flex-col lg:text-center gap-4 lg:gap-0 mb-5">
                  <div className="w-14 h-14 lg:w-20 lg:h-20 bg-brand-100 text-brand-600 rounded-full flex items-center justify-center text-2xl lg:text-4xl shrink-0 lg:mb-3 shadow-sm">🐶</div>
                  <div>
                    <h3 className="font-bold text-gray-900 text-lg">Барни</h3>
                    <p className="text-xs text-gray-500 mt-0.5">Золотистый ретривер • 3 мес.</p>
                  </div>
                </div>

                <div className="bg-red-50 text-red-700 p-4 rounded-xl mb-5 text-sm border border-red-100">
                  <span className="font-bold block mb-1">🆘 Причина вызова:</span>
                  Щенок проглотил кусок пластиковой игрушки 10 минут назад.
                </div>

                <h4 className="font-bold text-gray-900 text-sm mb-3">Быстрые рекомендации</h4>
                <div className="flex flex-col gap-2">
                  <button className="flex items-center justify-between p-3.5 border border-gray-200 rounded-xl hover:bg-gray-50 text-sm text-left group transition-colors">
                    <span className="font-bold text-gray-700">Наблюдение за ЖКТ</span>
                    <Send size={14} className="text-gray-400" />
                  </button>
                  <button className="flex items-center justify-between p-3.5 bg-brand-50 border border-brand-200 rounded-xl hover:bg-brand-100 text-sm text-left transition-colors mt-2">
                    <span className="font-bold text-brand-700 flex items-center gap-2"><MessageSquareHeart size={16} /> Направить в клинику</span>
                  </button>
                </div>
              </Card>
            </div>
        )}
      </div>
  );
};

export default SosPage;