import React from 'react';
import useClientStore from '../store/useClientStore';
import { Card } from '../components/ui/Card';
import { Badge } from '../components/ui/Badge';
import { Search, X, Clock, FileText, AlertTriangle } from 'lucide-react';
import { cn } from '../components/ui/Card';

const ClientsPage = () => {
    const { clients, searchQuery, selectedClient, setSearchQuery, setSelectedClient } = useClientStore();

    const filtered = clients.filter(c =>
        c.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        c.phone.includes(searchQuery) ||
        c.petName.toLowerCase().includes(searchQuery.toLowerCase())
    );

    return (
        <div className="flex h-[calc(100vh-8rem)] md:h-[calc(100vh-6rem)] relative overflow-hidden min-w-0">

            {selectedClient && (
                <div className="fixed inset-0 bg-gray-900/40 backdrop-blur-sm z-30 md:hidden animate-in fade-in" onClick={() => setSelectedClient(null)} />
            )}

            {/* Обертка с min-w-0 не дает таблице сломать экран */}
            <div className={cn("flex-1 flex flex-col transition-all duration-300 w-full min-w-0", selectedClient ? "md:pr-[400px]" : "")}>

                <div className="flex flex-col sm:flex-row sm:items-center justify-between mb-4 flex-shrink-0 gap-3">
                    <h2 className="text-xl font-bold tracking-tight text-gray-900">База клиентов</h2>
                    <div className="relative w-full sm:w-72 shrink-0">
                        <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
                        <input
                            type="text"
                            placeholder="Поиск по телефону или питомцу..."
                            value={searchQuery}
                            onChange={e => setSearchQuery(e.target.value)}
                            className="pl-9 pr-4 py-2.5 sm:py-2 border border-gray-200 rounded-xl text-sm bg-white w-full focus:outline-none focus:border-brand-400 focus:ring-1 focus:ring-brand-400 shadow-sm transition-all"
                        />
                    </div>
                </div>

                {/* Карточка таблицы */}
                <Card className="flex-1 overflow-hidden p-0 rounded-2xl flex flex-col min-w-0 w-full">
                    <div className="overflow-x-auto overflow-y-auto w-full h-full">
                        <table className="w-full text-left border-collapse min-w-[600px]">
                            <thead className="bg-gray-50 border-b border-gray-200 text-xs sm:text-sm font-bold text-gray-600 sticky top-0 z-10 shadow-sm">
                            <tr>
                                <th className="px-4 md:px-6 py-4 bg-gray-50 whitespace-nowrap">Клиент / Телефон</th>
                                <th className="px-4 md:px-6 py-4 bg-gray-50 whitespace-nowrap">Питомец</th>
                                <th className="px-4 md:px-6 py-4 bg-gray-50 whitespace-nowrap">Последний визит</th>
                                <th className="px-4 md:px-6 py-4 bg-gray-50 whitespace-nowrap text-right">Выручка</th>
                            </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-100">
                            {filtered.map(client => (
                                <tr key={client.id} onClick={() => setSelectedClient(client)} className="hover:bg-brand-50/50 cursor-pointer transition-colors group">
                                    <td className="px-4 md:px-6 py-4">
                                        <div className="font-bold text-gray-900 text-sm">{client.name}</div>
                                        <div className="text-xs text-gray-500 mt-0.5">{client.phone}</div>
                                    </td>
                                    <td className="px-4 md:px-6 py-4">
                                        <div className="flex items-center gap-3">
                                            <div className="w-8 h-8 sm:w-10 sm:h-10 rounded-full bg-gray-100 flex items-center justify-center text-lg sm:text-xl shrink-0">
                                                {client.petBreed.includes('Кот') || client.petBreed.includes('Мейн') ? '🐈' : '🐶'}
                                            </div>
                                            <div>
                                                <div className="font-bold text-gray-900 group-hover:text-brand-600 transition-colors flex items-center flex-wrap gap-1 text-sm">
                                                    {client.petName}
                                                    {client.isPremium && <Badge icon="premium" variant="ozon" className="scale-75 origin-left hidden sm:inline-flex">Ozon</Badge>}
                                                </div>
                                                <div className="text-xs text-gray-500 mt-0.5">{client.petBreed} • {client.age}</div>
                                            </div>
                                        </div>
                                    </td>
                                    <td className="px-4 md:px-6 py-4 text-xs sm:text-sm text-gray-600">{client.lastVisit}</td>
                                    <td className="px-4 md:px-6 py-4 text-right">
                                        <span className="font-black text-gray-900 text-sm">{client.ltv.toLocaleString()} ₽</span>
                                    </td>
                                </tr>
                            ))}
                            </tbody>
                        </table>
                    </div>
                </Card>
            </div>

            {/* Drawer */}
            <div className={cn("fixed md:absolute top-0 right-0 bottom-0 w-full sm:w-[400px] bg-white border-l border-gray-200 shadow-2xl transition-transform duration-300 flex flex-col z-40 md:z-20", selectedClient ? "translate-x-0" : "translate-x-full")}>
                {selectedClient && (
                    <>
                        <div className="px-4 md:px-6 py-3 md:py-4 border-b border-gray-100 flex items-center justify-between bg-gray-50/50 shrink-0">
                            <span className="font-bold text-gray-900 text-sm md:text-base">Pet ID Card</span>
                            <button onClick={() => setSelectedClient(null)} className="p-2 hover:bg-gray-200 rounded-lg text-gray-500"><X size={20} /></button>
                        </div>

                        <div className="flex-1 overflow-y-auto p-4 md:p-6 hide-scrollbar">
                            <div className="flex flex-col items-center text-center mb-6">
                                <div className="w-20 h-20 md:w-24 md:h-24 rounded-full bg-gray-100 flex items-center justify-center text-4xl md:text-5xl mb-3 shadow-sm border border-gray-200">
                                    {selectedClient.petBreed.includes('Кот') || selectedClient.petBreed.includes('Мейн') ? '🐈' : '🐶'}
                                </div>
                                <h2 className="text-xl md:text-2xl font-bold text-gray-900">{selectedClient.petName}</h2>
                                <p className="text-sm text-gray-500 mt-1">{selectedClient.petBreed} • {selectedClient.age}</p>
                                {selectedClient.isPremium && <span className="text-xs font-bold text-ozon-600 bg-ozon-50 border border-ozon-100 px-3 py-1 rounded-full mt-3">Клиент из Ozon SuperApp</span>}
                            </div>

                            {selectedClient.allergies.length > 0 && (
                                <div className="bg-red-50 border border-red-100 rounded-xl p-4 mb-6 flex gap-3 text-red-700">
                                    <AlertTriangle className="flex-shrink-0 mt-0.5" size={18} />
                                    <div>
                                        <p className="font-bold text-sm mb-1">Опасные аллергии!</p>
                                        <p className="text-sm font-medium">{selectedClient.allergies.join(', ')}</p>
                                    </div>
                                </div>
                            )}

                            <div className="mb-6">
                                <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-2 px-1">Владелец</h3>
                                <div className="bg-gray-50 rounded-xl p-4 border border-gray-100">
                                    <p className="font-bold text-gray-900 text-sm">{selectedClient.name}</p>
                                    <p className="text-sm text-gray-600 mt-1">{selectedClient.phone}</p>
                                </div>
                            </div>

                            <div className="border-b border-gray-200 flex gap-6 mb-4">
                                <div className="pb-3 border-b-2 border-brand-600 font-bold text-sm text-brand-700">История визитов</div>
                                <div className="pb-3 font-semibold text-sm text-gray-400">Файлы (2)</div>
                            </div>

                            <div className="flex flex-col gap-4 relative before:absolute before:inset-0 before:ml-[11px] before:h-full before:w-0.5 before:bg-gray-200 pt-2">
                                <div className="relative flex items-start w-full">
                                    <div className="flex items-center justify-center w-6 h-6 rounded-full bg-brand-100 border border-brand-200 text-brand-600 z-10 shrink-0"><Clock size={12} /></div>
                                    <div className="ml-4 w-full bg-gray-50 p-3 rounded-xl border border-gray-100">
                                        <h4 className="text-sm font-bold text-gray-900">Осмотр и Вакцинация</h4>
                                        <p className="text-xs font-medium text-gray-500 mt-1">{selectedClient.lastVisit}</p>
                                    </div>
                                </div>
                            </div>
                        </div>

                        <div className="p-4 border-t border-gray-100 bg-white shrink-0">
                            <button className="w-full flex justify-center items-center gap-2 bg-gray-900 hover:bg-black text-white py-3.5 md:py-3 rounded-xl text-sm font-bold shadow-lg transition-transform hover:-translate-y-0.5">
                                <FileText size={16} /> Добавить заключение
                            </button>
                        </div>
                    </>
                )}
            </div>
        </div>
    );
};

export default ClientsPage;